<?php
namespace Core\Pan;require_once __DIR__.'/../Guard.php';ml_guard_shield(__FILE__);require_once __DIR__.'/BasePan.php';class MagnetPan extends BasePan{public function transfer($a){$b=trim((string)$this->url);if($b===''){return $this->err('请提供磁力链接');}if($this->isType===1){return $this->ok('检验成功',array('title'=>$this->magnetTitle($b),'share_url'=>$b,));}return $this->ok('转存成功',array('title'=>$this->magnetTitle($b),'share_url'=>$b,'fid'=>'',));}public function getFiles($a='0'){return $this->err('磁力链接没有目录可选');}private function magnetTitle($a){if(preg_match('/[?&]dn=([^&]+)/',$a,$b)){$c=urldecode($b[1]);if($c!==''){return $c;}}if(preg_match('#magnet:\?xt=urn:btih:([a-fA-F0-9]{40})#',$a,$b)){return'磁力资源_'.substr($b[1],0,8);}return'磁力资源';}}